  }
}];

const config = $('Normalize Input').first().json;
const language = config.language;
const count = config.count;
const minLength = config.minLength;
const maxLength = config.maxLength;

const normalizeWord = (word) => String(word)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Za-z]/g, '')
  .toUpperCase();

const shuffle = (array) => {
  const copy = [...array];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[randomIndex]] = [copy[randomIndex], copy[index]];
  }
  return copy;
};

const payload = items.map(item => item.json);
const seen = new Set();
const allCandidates = [];

for (const item of payload) {
  const rawWord = String(item.word ?? '').trim();
  if (!rawWord) continue;
  const cleaned = normalizeWord(rawWord);
  if (!cleaned) continue;
  if (cleaned.length < minLength || cleaned.length > maxLength) continue;
  if (seen.has(cleaned)) continue;
  seen.add(cleaned);
  allCandidates.push(cleaned);
}

if (allCandidates.length < count) {
  throw new Error(`Solo se obtuvieron ${allCandidates.length} candidatas despues del filtrado.`);
}

const candidates = shuffle(allCandidates).slice(0, Math.min(25, allCandidates.length));

return [{
  json: {
    language,
    count,
    candidates
  }
}];

