const fallback = $('Filter Candidates').first().json;
const candidates = fallback.candidates;
const language = fallback.language;
const count = fallback.count;

const normalizeWord = (word) => String(word)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Za-z]/g, '')
  .toUpperCase();

let text = '';
try {
  text = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
} catch (error) {
  text = '';
}

let parsedWords = [];
try {
  const cleanedText = text.trim().replace(/^```json\s*/i, '').replace(/^```/i, '').replace(/```$/i, '').trim();
  const parsed = JSON.parse(cleanedText);
  if (Array.isArray(parsed.words)) {
    parsedWords = parsed.words;
  }
} catch (error) {
  parsedWords = [];
}

const finalWords = [];
const seen = new Set();
for (const word of parsedWords) {
  const cleaned = normalizeWord(word);
  if (!cleaned) continue;
  if (seen.has(cleaned)) continue;
  seen.add(cleaned);
  finalWords.push(cleaned);
  if (finalWords.length >= count) break;
}

if (finalWords.length < count) {
  for (const word of candidates) {
    const cleaned = normalizeWord(word);
    if (!cleaned) continue;
    if (seen.has(cleaned)) continue;
    seen.add(cleaned);
    finalWords.push(cleaned);
    if (finalWords.length >= count) break;
  }
}

if (finalWords.length < count) {
  throw new Error(`No fue posible completar ${count} palabras validas.`);
}

return [{
  json: {
    language,
    words: finalWords.slice(0, count)
  }
}];
